function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 500) return 'grid needs 1 to 500 rows.';
  if (grid.length % 2 === 0) return 'The number of rows m must be odd.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 500) return 'Each row needs 1 to 500 values.';
  if (n % 2 === 0) return 'The number of columns n must be odd.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    for (let j = 0; j < n; j++) {
      if (!Number.isInteger(row[j]) || row[j] < 1 || row[j] > 1000000) return 'Each value is an integer from 1 to 10^6.';
      if (j > 0 && row[j - 1] > row[j]) return 'Each row must be sorted in non-decreasing order.';
    }
  }
  return null;
}

