function matrixMedian(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const need = Math.floor((rows * cols) / 2) + 1;
  let low = Math.min(...grid.map(row => row[0]));
  let high = Math.max(...grid.map(row => row[cols - 1]));

  while (low < high) {
    const guess = Math.floor((low + high) / 2);
    let count = 0;
    for (const row of grid) {
      let left = 0;
      let right = cols;
      while (left < right) {
        const middle = Math.floor((left + right) / 2);
        if (row[middle] <= guess) {
          left = middle + 1;
        } else {
          right = middle;
        }
      }
      count += left;
    }
    if (count >= need) {
      high = guess;
    } else {
      low = guess + 1;
    }
  }
  return low;
}

