function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const odd = (lo, hi) => 2 * pick(lo, hi) + 1;
  const m = size === 'small' ? odd(0, 3) : odd(30, 49);
  const n = size === 'small' ? odd(0, 3) : odd(30, 49);
  const top = rand() < 0.4 ? (size === 'small' ? 4 : 50) : (size === 'small' ? 30 : 1000000);
  const bottom = rand() < 0.2 ? Math.floor(top / 2) : 1;
  const grid = [];
  for (let r = 0; r < m; r++) {
    const row = Array.from({ length: n }, () => pick(bottom, top));
    row.sort((a, b) => a - b);
    grid.push(row);
  }
  return [grid];
}
